"""Rebuild the report's numerical section from retained raw-derived summaries."""
import json,statistics
from pathlib import Path
root=Path('docs/mission-09-captures')
d=json.load(open(root/'summary.json'));m=json.load(open(root/'memory-validation.json'));r=json.load(open(root/'runtime-validation.json'))
b=d['benchmark']['phases']['before'];a=d['benchmark']['phases']['after']
rows=['| Station / profil | 08.6 médiane synchronisée | 09 médiane synchronisée | Écart |','| --- | ---: | ---: | ---: |']
for key,label in [('village','Village · Qualité'),('foret-dense','Forêt proche · Qualité'),('riviere','Rivière · Qualité'),('aerienne','Vue aérienne · Qualité'),('eco','Éco ordinateur'),('mobile','Mobile Éco émulé')]:
 x=b['stations'][key]['synchronizedRenderMs']['p50'];y=a['stations'][key]['synchronizedRenderMs']['p50'];rows.append(f'| {label} | {x:.1f} ms | {y:.1f} ms | {(y/x-1)*100:+.1f} % |')
text='\n'.join(rows)+'\n\nLes chiffres regroupent 45 échantillons synchronisés par station et version (15 × 3 passages). Les six passages finaux sont réalisés sur le vent corrigé (`033df74`), sans modifier le rendu entre passages. Le rendu logiciel régresse sur plusieurs vues : ce coût n’est pas masqué par une réduction de géographie. Les différences de signe entre scènes et la dispersion des passages interdisent une conclusion générale de gain de fluidité. Les essais intermédiaires et de timer GPU ne sont pas mélangés à ce tableau.\n\n'
text+=f"Chargement local médian : {b['loads']['p50']/1000:.3f} → {a['loads']['p50']/1000:.3f} s, trois pages neuves par version ; maxima {b['loads']['max']/1000:.3f} → {a['loads']['max']/1000:.3f} s. Cette différence n’établit pas un gain de démarrage en production.\n\n"
text+='| Boucle réelle · mobile Éco à l’arrêt | 08.6 | 09 |\n| --- | ---: | ---: |\n'
for key,label in [('mobileIntervals','Intervalle d’image'),('mobileCpu','CPU avant soumission'),('mobileSubmit','Soumission CPU')]:
 for q in ['p50','p95','p99','max']:text+=f"| {label} {q} | {b[key][q]:.1f} ms | {a[key][q]:.1f} ms |\n"
text+='\nCette courte trace comprend 120 images par version (40 × 3), après dix images d’échauffement. Elle conserve les pics et ne remplace pas une mesure sur appareil. Les marches ci-dessous constituent un scénario distinct et plus long.\n\n'
cpu=[v['atmosphereCpuMs']['p95'] for p in [b,a] for v in p['stations'].values()]
x=a['stations']['aerienne'];text+=f"Le p95 de la mise à jour entière d’atmosphère est compris entre {min(cpu):.1f} et {max(cpu):.1f} ms selon la station et la version ; la résolution des mesures est d’environ 0,1 ms. Le temps synchronisé inclut le pilote logiciel et la lecture des pixels : il n’est pas une durée GPU matérielle. L’essai aérien sans ombres donne {x['withoutCloudShadowsMs']['p50']:.1f} ms médians, contre {x['synchronizedRenderMs']['p50']:.1f} ms avec ombres ; la dispersion ne permet pas d’en isoler précisément le coût. L’extension de timer GPU est annoncée par SwiftShader, mais plusieurs requêtes restent indisponibles : aucune estimation matérielle n’est publiée.\n\n"
text+='Les draw calls sont stables dans cinq stations (80, 102, 161, 98 et 54 selon la vue), et passent de 125 à 124 au village. Les triangles baissent de 192 dans les vues Qualité, et de 1 248 en Éco : seules les représentations atmosphériques ont changé. Les arbres, bâtiments, terrain et routes sont identiques. Les nombres de faune et d’événements sont conservés dans les traces ; neuf objets CPU sont réservés en Éco, dix dans les autres profils, sans boucle CPU par arbre.\n\n'
b=d['walk-before'];a=d['walk-after']
text+='| Promenade réelle, même route | 08.6 | 09 |\n| --- | ---: | ---: |\n'+f"| Distance mesurée image par image | {b['metres']:.6f} m | {a['metres']:.6f} m |\n| Durée murale de marche | {b['seconds']:.1f} s | {a['seconds']:.1f} s |\n| Images mobiles dans la trace | {b['frames']} | {a['frames']} |\n"
for key,label in [('cpu','CPU avant soumission'),('intervals','Intervalle d’image'),('submit','Soumission CPU')]:
 for q in ['p50','p95','p99','max']:text+=f"| {label} {q} | {b[key][q]:.1f} ms | {a[key][q]:.1f} ms |\n"
text+='\nLes deux marches atteignent 450 m sans téléportation au lancement, passent le zoom, le pincement et les trois caméras, et ne régénèrent pas l’architecture. Le pincement est testé sur une partie dégagée du canvas. La marche 09 finale est refaite sur `033df74`, avec correction du repère de vent et des interrupteurs personnalisés ; la référence 08.6 est `f11f165`. La marche intermédiaire 09 demeure accessible dans l’historique Git mais n’est pas mélangée aux chiffres finaux. Le pas de simulation borné à 250 ms explique qu’un rendu logiciel lent allonge la durée murale.\n\n'
text+=f"Heap JavaScript maximal sur les marches : {b['heap']['max']/1e6:.2f} → {a['heap']['max']/1e6:.2f} Mo. Ce n’est ni le RSS, ni la VRAM, ni une preuve de stabilité sur plusieurs heures. Les mêmes 23 blocs sont demandés, décodés et installés, avec 2 978 046 octets demandés, 15 annulations, zéro échec et zéro résultat périmé. Les pics de décodage CPU sont de 3,1 → 1,2 ms, d’installation 1,6 → 0,7 ms et de tick 2,5 → 2,3 ms ; le maximum de récupération/décodage mural augmente de 126,5 à 324,3 ms. Ces variations ne sont pas attribuées à une modification du chargeur. Aucun déchargement nécessaire n’a été observé sur ce trajet monotone ; les tests distincts de retour, éviction et démontage complètent donc la marche.\n\n"
text+='| Mémoire retenue, scène et caches amorcés | 08.6 | 09 |\n| --- | ---: | ---: |\n'
for n in ['village','foret','eco']:
 x=m['results']['before']['stations'][n];y=m['results']['after']['stations'][n];text+=f"| Géométrie + instances · {n} | {x['geometryAndInstanceBytes']/1e6:.3f} Mo | {y['geometryAndInstanceBytes']/1e6:.3f} Mo |\n"
x=m['results']['before']['stations']['foret'];y=m['results']['after']['stations']['foret'];text+=f"| Textures source + mipmaps estimées · forêt | {x['estimatedTextureBytes']/1e6:.3f} Mo | {y['estimatedTextureBytes']/1e6:.3f} Mo |\n| Textures téléversées · forêt | {x['uploadedTextures']} | {y['uploadedTextures']} |\n"
text+='\nL’audit inclut les matrices/couleurs d’instances, les géométries retenues hors écran et les textures des matériaux/uniformes compilés. Il ne mesure pas la mémoire privée du pilote. Le surcroît retenu est de 120 064 octets de géométrie, dont les grilles de nuages bornées ; aucune texture nouvelle. Les résidences et détails par station sont conservés dans `memory-validation.json`.\n\n'
t=r['lifecycle']['timings'];text+=f"Sur douze créations/destructions supplémentaires de la couche naturelle : création CPU médiane {statistics.median(v['createCpuMs'] for v in t):.2f} ms, maximum {max(v['createCpuMs'] for v in t):.2f} ms ; destruction CPU médiane {statistics.median(v['disposeCpuMs'] for v in t):.2f} ms, maximum {max(v['disposeCpuMs'] for v in t):.2f} ms. Ces cycles sans compilation GPU supplémentaire vérifient le démontage et les allocations CPU, pas la libération instantanée de VRAM.\n\n"
text+='Les quatre fichiers `realtime-*-foret.webm` et `realtime-*-mobile-eau.webm` contiennent six secondes murales de la boucle normale avant/après, après chargement, sans pas de simulation manuel ni interpolation d’image. Ils complètent les WebP et montrent les limites du rendu logiciel. Le test de pixels vérifie aussi deux images identiques lorsque le courant est coupé, puis deux images différentes après réactivation.\n'
p=Path('docs/mission-09.md');s=p.read_text();start=s.index('| Station / profil |');end=s.index('\n## Limites et extension mondiale',start);p.write_text(s[:start]+text+s[end:])
